// 예약 폼 페이지
// 방문자(학부모/학생)가 상담 예약을 입력하고 제출하는 화면
// 제출 성공 시 ConfirmPage로 이동하며 예약 정보를 함께 전달한다

import { useState } from "react";
import { useNavigate } from "react-router-dom";
import DatePicker from "react-datepicker";
import "react-datepicker/dist/react-datepicker.css";
import { createReservation } from "../api/reservations";

// 예약 가능한 시간대 목록 (09시~16시, 정수로 표현)
const TIME_SLOTS = [9, 10, 11, 12, 13, 14, 15, 16];

// 예약 가능한 날짜 필터 함수
// react-datepicker의 filterDate prop에 전달하여 선택 불가 날짜를 회색으로 표시
const isWeekday = (date) => {
  const day = date.getDay(); // 0=일요일, 6=토요일
  return day !== 0 && day !== 6; // 평일만 true 반환
};

function ReservationPage() {
  const navigate = useNavigate();

  // 폼 입력값 상태
  const [name, setName] = useState("");
  const [phone, setPhone] = useState("");
  const [selectedDate, setSelectedDate] = useState(null); // react-datepicker는 Date 객체 사용
  const [timeSlot, setTimeSlot] = useState("");

  // 로딩 및 에러 상태
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  // 날짜 범위 계산: 오늘 ~ 2주 후
  const today = new Date();
  const twoWeeksLater = new Date();
  twoWeeksLater.setDate(today.getDate() + 14);

  // Date 객체를 FastAPI가 받는 형식(YYYY-MM-DD)으로 변환
  const formatDate = (date) => {
    const y = date.getFullYear();
    const m = String(date.getMonth() + 1).padStart(2, "0"); // 월은 0부터 시작하므로 +1
    const d = String(date.getDate()).padStart(2, "0");
    return `${y}-${m}-${d}`;
  };

  const handleSubmit = async (e) => {
    e.preventDefault(); // 폼 기본 제출 동작(페이지 새로고침) 방지

    // 날짜 선택 여부 확인 (나머지는 HTML required로 검증)
    if (!selectedDate) {
      setError("날짜를 선택해주세요.");
      return;
    }

    setLoading(true);
    setError("");

    try {
      // FastAPI POST /reservations 호출
      const result = await createReservation({
        name,
        phone,
        date: formatDate(selectedDate),
        time_slot: parseInt(timeSlot), // 문자열 → 정수 변환
      });

      // 예약 성공 시 확인 페이지로 이동
      // state로 예약 정보를 전달하여 ConfirmPage에서 표시
      navigate("/confirm", { state: { reservation: result } });
    } catch (err) {
      // FastAPI에서 반환한 에러 메시지 표시
      // err.response.data.detail: FastAPI HTTPException의 detail 필드
      setError(err.response?.data?.detail || "예약 중 오류가 발생했습니다.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ maxWidth: 480, margin: "60px auto", padding: "0 20px" }}>
      <h2>상담 예약</h2>
      <p style={{ color: "#666" }}>평일 09:00 ~ 16:00 / 1시간 단위</p>

      <form onSubmit={handleSubmit}>

        {/* 이름 입력 */}
        <div style={{ marginBottom: 16 }}>
          <label>이름</label>
          <input
            type="text"
            value={name}
            onChange={(e) => setName(e.target.value)}
            placeholder="홍길동"
            required
            style={{ display: "block", width: "100%", padding: 8, marginTop: 4 }}
          />
        </div>

        {/* 전화번호 입력 */}
        <div style={{ marginBottom: 16 }}>
          <label>전화번호</label>
          <input
            type="tel"
            value={phone}
            onChange={(e) => setPhone(e.target.value)}
            placeholder="01012341234"
            required
            style={{ display: "block", width: "100%", padding: 8, marginTop: 4 }}
          />
        </div>

        {/* 날짜 선택 (react-datepicker) */}
        <div style={{ marginBottom: 16 }}>
          <label>날짜</label>
          <div style={{ marginTop: 4 }}>
            <DatePicker
              selected={selectedDate}
              onChange={(date) => setSelectedDate(date)}
              filterDate={isWeekday}       // 주말 선택 불가
              minDate={today}              // 오늘 이전 선택 불가
              maxDate={twoWeeksLater}      // 2주 이후 선택 불가
              dateFormat="yyyy-MM-dd"
              placeholderText="날짜 선택"
              style={{ padding: 8 }}
            />
          </div>
        </div>

        {/* 시간대 선택 */}
        <div style={{ marginBottom: 24 }}>
          <label>시간</label>
          <select
            value={timeSlot}
            onChange={(e) => setTimeSlot(e.target.value)}
            required
            style={{ display: "block", width: "100%", padding: 8, marginTop: 4 }}
          >
            <option value="">시간 선택</option>
            {TIME_SLOTS.map((slot) => (
              // 정수 시간을 "09:00 ~ 10:00" 형식으로 표시
              <option key={slot} value={slot}>
                {String(slot).padStart(2, "0")}:00 ~ {String(slot + 1).padStart(2, "0")}:00
              </option>
            ))}
          </select>
        </div>

        {/* 에러 메시지 표시 */}
        {error && (
          <p style={{ color: "red", marginBottom: 16 }}>{error}</p>
        )}

        {/* 제출 버튼 */}
        <button
          type="submit"
          disabled={loading}
          style={{ width: "100%", padding: 12, fontSize: 16 }}
        >
          {loading ? "예약 중..." : "예약하기"}
        </button>
      </form>
    </div>
  );
}

export default ReservationPage;
